INSERT INTO feature VALUES('mutual-recursion','recursion','Mutual recursion blocks',NULL,'implemented','ordinary',NULL,'A rec { … } block whose members see each other, lowered to one fixpoint over the sum of the members'' domains, admitted once. A member descends on its first parameter and passes the parameters after it to its siblings, unchanged or varied. Members whose later parameters differ, or whose types read the first, share the fixpoint at a goal that a case over the sum computes, and each member reads its own type there in the checker and the kernel. The block''s data families that share their parameters also read as one description over their sorts, a field at a sibling a recursive occurrence at its sort, and the decoder reads each sort to its family.','core-term core-checker kernel-core surface-lowering surface-lowering-base','corpus/model/data/rose.gandr corpus/model/desc/stlc.gandr crates/surface-lowering-base/src/description/tests.rs::a_mutual_block_s_data_families_read_as_one_description_5018 crates/core-term/src/description/tests.rs::each_sort_of_a_mutual_description_decodes_to_its_family_5018','corpus/model/data/rose.gandr','');
